#!/bin/sh
# SPDX-FileCopyrightText: 2026 VectoDE
# SPDX-License-Identifier: GPL-3.0-or-later
# Assembles the GitHub Pages site into build/pages/:
#   /de/, /en/  the website, generated by site/build.mjs from site/src/pages.mjs and site/site.config.json
#   /           language choice (x-default), plus sitemap.xml, robots.txt, llms.txt and 404.html
#   /assets/    styles, script and the self-hosted fonts (WOFF2 subsets of branding/fonts)
#   /brand/     brand guide and all assets from branding/ (without the generators in branding/tools/)
#   /api/       OpenAPI description of the REST API (docs/cloud/api.openapi.yaml) and the gRPC
#               interface (cloud/api/src/main/resources/vectolyn/api/v1/cloud.proto, at its import path)
# Every link in the output is relative, so the site works under any base path such as /VectolynCloud/.
# Needs Node.js 18 or newer and nothing else.
set -eu

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
out="$root/build/pages"

rm -rf "$out"
mkdir -p "$out/brand" "$out/api/vectolyn/api/v1"
node "$root/site/build.mjs"
cp "$root/docs/cloud/api.openapi.yaml" "$out/api/openapi.yaml"
cp "$root/cloud/api/src/main/resources/vectolyn/api/v1/cloud.proto" "$out/api/vectolyn/api/v1/cloud.proto"
(cd "$root/branding" && tar -cf - --exclude=./tools .) | (cd "$out/brand" && tar -xf -)

echo "Site written to $out"
